import {getGlowCapacity,getLifeCapacity,formatGlow} from './vitality.mjs?v=plain-begin-1';
import {livesMarkup} from './lives.mjs?v=plain-begin-1';
import {resourceSymbol} from './game-symbols.mjs?v=plain-begin-1';
import {choiceScene} from './choice-art.mjs?v=plain-begin-1';
import {mapStopIconMarkup} from './map-guide.mjs?v=plain-begin-1';
import {dreamRestMarkup} from './dream.mjs?v=plain-begin-1';
import {skillIcon,artifactIcon} from './upgrade-icons.mjs?v=plain-begin-1';
import {companionArtSvg} from './companion-art.mjs?v=plain-begin-1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function restBenefitsMarkup(run,node,choices=[],{nextNode=null}={}){
 const capacity=getGlowCapacity(run),fullHearts={...run,lives:getLifeCapacity(run)},resolved=run.restReady===true;
 const offers=resolved?[{title:'Recover',effect:{rest:'recover'}},{title:'Grow',effect:{rest:'grow'}}]:choices;
 return `<section class="rest-choice-screen rest-simple rest-one-scene ${resolved?'rest-benefit-resolved':''}"><aside class="rest-rail"><div class="rest-place-art">${mapStopIconMarkup(node)}</div><span class="rest-eyebrow">REST · MAP ${run.mapIndex+1}/3</span><h1>${esc(node.name)}</h1><div class="rest-vitals" ${resolved?'role="status"':''}>${livesMarkup(run)}<span class="rest-glow" aria-label="${formatGlow(run.flame)} of ${formatGlow(capacity)} Energy">${resourceSymbol('glow')}<b>${formatGlow(run.flame)}<small>/${formatGlow(capacity)}</small></b></span></div>${resolved?`<span class="rest-receipt">✓ ${run.lastRest?.boon==='grow'?'Capacity grown':'Hearts restored'}</span><button class="rest-route-link" data-action="view-route">View route</button>`:`<details class="rest-rules"><summary>ⓘ Rest rules</summary><div>${choices.map(c=>`<p><b>${esc(c.title)}</b>${esc(c.description)}</p>`).join('')}<p>Choose once. Both refill Energy without creating Packed Sparks.</p></div></details>`}</aside><div class="rest-benefit-area"><div class="rest-choice-caption"><b>${resolved?'RESTORED':'CHOOSE ONE'}</b><span class="rest-refill-note">${resourceSymbol('glow')} ${resolved?'Ready when you are':'Both refill Energy'}</span></div><div class="rest-benefit-cards" style="--rest-choice-count:2">${offers.map((c,index)=>{
 const grow=c.effect.rest==='grow',gain=Math.max(0,c.effect.glowCapacity||0),after=capacity+gain,selected=resolved&&run.lastRest?.boon===c.effect.rest;
 return `<${resolved?'article':'button'} class="rest-benefit ${selected?'rest-boon-chosen':''} ${resolved&&!selected?'rest-boon-passed':''}" ${resolved?'':`data-action="support" data-index="${index}" ${c.disabled?'disabled':''} aria-label="${esc(c.title+'. '+c.description)}"`}>${choiceScene(grow?'refillGlow':'hearts')}<h2>${esc(c.title)}</h2>${resolved?`<span class="rest-chosen-mark">${selected?'✓ CHOSEN':'—'}</span>`:grow?`<span class="rest-capacity-gain">${c.disabled?'✓ ✓ ✓':`<b>+${formatGlow(gain)}</b> ${resourceSymbol('glow')} MAX`}</span>`:`<span class="rest-heart-result">${livesMarkup(run)}<i aria-hidden="true">→</i>${livesMarkup(fullHearts)}</span>`}${!resolved&&!c.disabled?`<span class="rest-full-sparks" aria-label="Refills to ${formatGlow(after)} of ${formatGlow(after)} Energy">${resourceSymbol('glow')}<b>${formatGlow(after)}<small>/${formatGlow(after)}</small></b></span>`:''}${!resolved?`<span class="rest-pick-cue">${c.disabled?'CAPACITY FULL':'CHOOSE →'}</span>`:''}</${resolved?'article':'button'}>`;
 }).join('')}</div>${resolved?`<nav class="rest-optional-tools" aria-label="Optional Rest preparation"><button data-action="skills">${skillIcon({id:'main-sight',branch:'main'})}<span>Skills</span></button><button data-action="companions">${companionArtSvg(run.companionRole||'collector')}<span>Companion</span></button><button data-action="artifacts">${artifactIcon(run.artifacts?.find(Boolean)||'glow-wick')}<span>Collection</span></button>${nextNode?dreamRestMarkup(run,nextNode):''}</nav><footer class="rest-leave-row">${nextNode?`<span>Next · ${esc(nextNode.name)}</span><button class="primary rest-depart" data-action="node" data-id="${esc(nextNode.id)}">Leave Rest <span aria-hidden="true">→</span></button>`:'<button class="primary" data-action="view-route">Return to route →</button>'}</footer>`:''}</div></section>`;
}
